-- Holiday vendors that 970 (post-Wrath removal) cut: their templates and wares, put back unspawned.
-- 2026_11_19_977_world_everlake_holiday_vendors_restore.sql: written by hand; the rows below are copied from a world built
-- the way CI builds the PTR's, just before 970.
--
-- 970 cut these six creature templates because they are not in AzerothCore's 3.3.5 world and nothing spawns them. They
-- sell Forever items that no source on the realm gives yet (the tracker lists them as incomplete), so spawning them for
-- the holidays is the likely fix. That needs their templates back:
--   52497 Spanky, 53760 Farina (Hallow's End masks, 16 items each)
--   53702 Stymie, 53756 Darla (Hallow's End wands, 8 items each)
--   211812 Kiera Torres (Love is in the Air: Bag of Candies)
--   211873 Bang Sparknozzle (Love is in the Air: Love Fool)
-- They are copied as they were before 970: templates, difficulties, models, locales, addons and all 125 vendor rows.
-- Nothing is spawned here, so nothing changes in game until a later file or the Forge spawns them. Whether Forever
-- uses these exact vendors isn't confirmed.
--
-- A row goes in only where it is missing, and each template it adds is recorded in everlake_import_rows. Running it
-- again changes nothing. Not checked in game. Never edit this file once it is deployed: a later fix is a new file.


CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

START TRANSACTION;


